    "question": "Trong những câu nói sau đây, câu nào không phải là của Hồ Chí Minh? A \"Muốn được dân yêu, muốn được lòng dân, trước hết phải yêu dân, phải đặt quyền lợi của dân trên hết thảy, phải có một tinh thần chí công vô tư\".",
    "question_vi": "Trong những câu nói sau đây, câu nào không phải là của Hồ Chí Minh? A \"Muốn được dân yêu, muốn được lòng dân, trước hết phải yêu dân, phải đặt quyền lợi của dân trên hết thảy, phải có một tinh thần chí công vô tư\".",
